+// --plan-journey (temporary, uncommitted): the live adapter's requests with
+// OpenRouter's host routing added, as tests/project_prompt pins it.
+class PinnedHostsTransport final : public Agent::IAgentHttpTransport
+{
+public:
+    PinnedHostsTransport(std::unique_ptr<Agent::IAgentHttpTransport> inner, std::vector<std::string> hosts)
+        : m_inner(std::move(inner)), m_hosts(std::move(hosts)) {}
+    bool post(Agent::AgentHttpRequest request, EventFn event) override
+    {
+        nlohmann::json body = nlohmann::json::parse(request.body);
+        if (!m_hosts.empty())
+            body["provider"] = {{"order", m_hosts}, {"allow_fallbacks", false}};
+        // The pinned hosts take no image input, as tests/project_prompt
+        // notes: pictures are dropped, and an item left with no content goes.
+        int dropped = 0;
+        std::function<void(nlohmann::json&)> strip = [&](nlohmann::json& value) {
+            if (value.is_array()) {
+                for (auto item = value.begin(); item != value.end();) {
+                    if (item->is_object() && item->value("type", "") == "input_image") {
+                        item = value.erase(item);
+                        ++dropped;
+                        continue;
+                    }
+                    strip(*item);
+                    if (item->is_object() && item->contains("content") && (*item)["content"].is_array() &&
+                        (*item)["content"].empty()) {
+                        item = value.erase(item);
+                        continue;
+                    }
+                    ++item;
+                }
+            } else if (value.is_object()) {
+                for (auto& [key, child] : value.items())
+                    strip(child);
+            }
+        };
+        strip(body["input"]);
+        if (dropped > 0)
+            std::cerr << "HARNESS JOURNEY dropped_images=" << dropped << '\n';
+        request.body = body.dump();
+        auto head = std::make_shared<std::string>();
+        return m_inner->post(std::move(request), [event = std::move(event), head](Agent::AgentHttpEvent http) {
+            if (http.kind == Agent::AgentHttpEvent::Kind::Data && head->size() < 600)
+                head->append(http.data.substr(0, 600 - head->size()));
+            if (http.kind == Agent::AgentHttpEvent::Kind::Error ||
+                (http.kind == Agent::AgentHttpEvent::Kind::Complete && http.status != 200))
+                std::cerr << "HARNESS JOURNEY HTTP status=" << http.status << " error=" << http.error
+                          << " body=" << *head << '\n';
+            event(std::move(http));
+        });
+    }
+    void cancel() override { m_inner->cancel(); }
+
+private:
+    std::unique_ptr<Agent::IAgentHttpTransport> m_inner;
+    std::vector<std::string> m_hosts;
+};
