#pragma once

// Every model request an Agent posts, written to a directory exactly as
// posted, for checking what a provider was sent and what it cached. Tests and
// the shell harness only; the app does not ship it. GUI-free.
//
// For the n-th request of a run (n from 1, four digits, in post order):
//   NNNN-request.json       the body, byte for byte as the transport got it
//   NNNN-request.meta.json  provider, URL, headers (credentials redacted),
//                           project and chat id, purpose, request id,
//                           attempt, time and body length
//   NNNN-response.sse       the response stream as it was received
//   NNNN-response.json      HTTP status, usage, stop reason, assembled text
//                           and any error, read from that stream
// The response files are written when the stream ends, fails, is cancelled or
// is replaced by the next request. tests/project_prompt/prefix_check.py reads
// the directory.

