namespace Slic3r::GUI::JusPrin::Agent {

class RequestLog
{
public:
    // Chat ids restart in each project, so a chat is named by both.
    struct Chat
    {
        std::string project_id;
        std::string chat_id;
    };

    // `directory` is created if missing and must hold nothing, so a run's
    // numbering never mixes with an earlier run's. `chat` names the chat a
    // request belongs to, read at each post.
    RequestLog(std::filesystem::path directory, std::function<Chat()> chat)
        : m_state(std::make_shared<State>())
    {
        std::filesystem::create_directories(directory);
        if (!std::filesystem::is_empty(directory))
            throw std::runtime_error("the request log directory is not empty: " + directory.string());
        m_state->directory = std::move(directory);
        m_state->chat      = std::move(chat);
    }

    // `inner`, with every request it is given logged first. `provider` is the
    // ProviderProfile id whose wire format the bodies are in.
    std::unique_ptr<IAgentHttpTransport> transport(std::string provider, std::unique_ptr<IAgentHttpTransport> inner) const
    {
        return std::make_unique<Transport>(m_state, std::move(provider), std::move(inner));
    }

    // `inner`, telling the log the purpose, request id and attempt of the
    // turn each later request belongs to. Its transport must be one of this
    // log's.
    AgentServicePtr agent(AgentServicePtr inner) const { return std::make_unique<Service>(m_state, std::move(inner)); }

private:
    struct State
    {
        std::filesystem::path        directory;
        std::function<Chat()>        chat;

    std::function<void()> m_wait_then;
    std::function<void()> m_wait_each_tick;
    bool                  m_idle_watch_bound{false};
    bool                  m_idle_armed{false};
    bool                  m_idle_seen{false};
};

// The app ships no stand-in Agent, so each mode's Agent is installed here
// through the host's own set_agent, the call setup uses when a key verifies.
void install_harness_agent(const HarnessState& state)
{
    ShellController* shell = installed_shell();
    if (shell == nullptr)
        return; // stock mode: the shell is disabled, so there is no Agent panel
    Agent::AgentHost& host = shell->agent_pane()->web_view().host();
    // --request-log: the provider modes' agent and transport, logging. The
    // printer panel's own Agent and an agent the host rebuilds for another
    // chosen model come from the app configuration and are not logged.
    std::optional<Agent::RequestLog> log;
    if (!state.request_log.empty())
        log.emplace(std::filesystem::path(state.request_log.native()), [&host] {
            const Agent::ProjectStateDocument& document = host.persistence().document();
            return Agent::RequestLog::Chat{document.project_id(), document.active_conversation_id()};
        });
    const auto transport = [&log](std::unique_ptr<Agent::IAgentHttpTransport> inner) {
        return log ? log->transport("openai", std::move(inner)) : std::move(inner);
    };
    const auto agent = [&log](Agent::AgentServicePtr inner) { return log ? log->agent(std::move(inner)) : std::move(inner); };
    const HarnessState::Mode mode = state.mode;
    switch (mode) {
    case HarnessState::Mode::LiveAgentUnavailable:
    case HarnessState::Mode::ManualUnconfigured:
        return;
    case HarnessState::Mode::LiveAgent:
    case HarnessState::Mode::ManualLiveAgent: {
        // Without a key the live checks report the missing service themselves.
        const char* key = std::getenv("OPENAI_API_KEY");
        if (key == nullptr || *key == '\0')
            return;
        // The printer panel builds its own Agent from the app configuration,
        // so hands-on printer setup needs the key there too: this run's
        // throwaway data directory, as --printer-live does. A std::string,
        // or AppConfig::set picks its bool overload.
        if (mode == HarnessState::Mode::ManualLiveAgent)
            wxGetApp().app_config->set("jusprin_agent", "openai_api_key", std::string(key));
        Agent::OpenAIResponsesConfig config;
        config.api_key = key;
        config.usage_listener = [](const Agent::AgentUsage& usage) {
            // cached_input_tokens is the evidence the tool-loading decision
            // rests on; report it on every request, not only when it is
            // non-zero, so a chat that stops caching is visible in the log.
            std::cerr << "JUSPRIN LIVE USAGE provider=openai input_tokens=" << usage.input
                      << " cached_input_tokens=" << usage.cached_input << " output_tokens=" << usage.output
                      << " total_tokens=" << usage.total << '\n';
        };
        host.set_agent(agent(std::make_unique<Agent::OpenAIResponsesAgent>(std::move(config),
                                                                           transport(Agent::make_openai_http_transport()))),
                       Agent::AgentAvailability::Ready);
        return;
    }
    case HarnessState::Mode::ProjectPromptRequests: {
        host.set_agent(agent(std::make_unique<Agent::OpenAIResponsesAgent>(Agent::OpenAIResponsesConfig{"sk-harness-not-a-real-key"},
                                                                           transport(std::make_unique<HeldModelTransport>()))),
                       Agent::AgentAvailability::Ready);
        return;
    }
    case HarnessState::Mode::ReplyChoicesCapture:
        host.set_agent(std::make_unique<ChoicesAgent>(), Agent::AgentAvailability::Ready);
        return;
    case HarnessState::Mode::CalibrationCapture:
        host.set_agent(std::make_unique<CalibrationAgent>(), Agent::AgentAvailability::Ready);
        return;
    case HarnessState::Mode::PrintIssues:
    case HarnessState::Mode::ManualPrintIssues: {
        if (g_issue_no_agent)
            return;
        auto agent = std::make_unique<RecordingAgent>();
        g_issue_agent = agent.get();
        host.set_agent(std::move(agent), Agent::AgentAvailability::Ready);
        return;
    }
    default: {
        auto agent   = std::make_unique<BodyRecordingMockAgent>();
        g_body_agent = agent.get();
        host.set_agent(std::move(agent), Agent::AgentAvailability::Ready);
        return;
    }
    }
}

void start_when_ready(GUI_App& app, const std::shared_ptr<HarnessState>& state)
{
    if (state->stop)
        return;
    if (std::chrono::steady_clock::now() >= state->deadline) {
        std::cerr << "HARNESS ERROR application did not become ready before timeout\n";
        state->result = 1;
        state->stop = true;
        app.ExitMainLoop();
        return;
    }
    if (app.mainframe != nullptr && app.plater() != nullptr) {
#ifdef __APPLE__
        if (state->dark_appearance) set_harness_appearance(*state->dark_appearance);
#endif
        install_harness_agent(*state);
