            // The selected profile must be a Bambu Lab one for the fake to
            // be the printer agent (GUI_App::switch_printer_agent).
            app.app_config->set("jusprin", "fake_printer", "true");
            app.switch_printer_agent();
            if (++index == argc) {
                std::cerr << "--tool-strip-capture requires an output directory\n";
                return 2;
            }
            state->mode = HarnessState::Mode::ToolStripCapture;
            state->capture_dir = fs::absolute(argv[index]);
        }
        else
            gui_arguments.emplace_back(argv[index]);
    }
    if (!state->request_log.empty() && state->mode != HarnessState::Mode::LiveAgent &&
        state->mode != HarnessState::Mode::ManualLiveAgent && state->mode != HarnessState::Mode::ProjectPromptRequests) {
        std::cerr << "--request-log works with --live-agent, --manual-live-agent and --project-prompt-requests\n";
        return 2;
    }
#ifdef __APPLE__
    if (state->dark_appearance) set_harness_appearance(*state->dark_appearance);
#endif
    fs::create_directories(data_directory / "log");
