import json
import re
import sys

TS = re.compile(r"\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d+)?Z")
TMP = re.compile(r"(?:/private)?/var/folders/[^\"\\]*?/T/jusprin-shell-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}")
PNG = re.compile(r"(?:data:image/png;base64,)?iVBORw0KGgo[A-Za-z0-9+/=]+")


def norm_text(text):
    return PNG.sub("<PNG>", TMP.sub("<TMP>", TS.sub("<TS>", text)))


def norm(value):
    if isinstance(value, str):
        text = norm_text(value)
        if text[:1] in "{[":
            try:
                return {"<json>": norm(json.loads(text))}
            except ValueError:
                pass
        return text
    if isinstance(value, list):
        return [norm(v) for v in value]
    if isinstance(value, dict):
        return {k: norm(v) for k, v in value.items()}
    return value


def diffs(a, b, path="", out=None):
    out = [] if out is None else out
    if type(a) != type(b):
        out.append((path, a, b))
    elif isinstance(a, dict):
        for key in sorted(set(a) | set(b)):
            if key not in a or key not in b:
                out.append((f"{path}/{key}", a.get(key, "<absent>"), b.get(key, "<absent>")))
            else:
                diffs(a[key], b[key], f"{path}/{key}", out)
    elif isinstance(a, list):
        for i in range(max(len(a), len(b))):
            if i >= len(a) or i >= len(b):
                out.append((f"{path}[{i}]", a[i] if i < len(a) else "<absent>", b[i] if i < len(b) else "<absent>"))
            else:
                diffs(a[i], b[i], f"{path}[{i}]", out)
    elif a != b:
        out.append((path, a, b))
    return out


def short(value, n=160):
    text = value if isinstance(value, str) else json.dumps(value, ensure_ascii=False)
    return text[:n].replace("\n", "\\n")


def main():
    old = json.load(open(sys.argv[1]))
    new = json.load(open(sys.argv[2]))
    limit = int(sys.argv[sys.argv.index("--paths") + 1]) if "--paths" in sys.argv else 4
    # settingItems is an index table; resolve it so a renumbering is not a change.
    for doc in (old, new):
        items = doc.get("settingItems", [])
        for case in doc["cases"].values():
            for answer in case.get("answers", []):
                if answer.get("settingItems"):
                    output = json.loads(answer["output"])
                    for field in ("items", "unknownKeys"):
                        if field in output.get("result", {}):
                            output["result"][field] = [items[i] for i in output["result"][field]]
                    answer["output"] = json.dumps(output, sort_keys=True)
    oc, nc = old["cases"], new["cases"]
    print(f"cases: old {len(oc)} new {len(nc)}; only old {sorted(set(oc) - set(nc))}; only new {sorted(set(nc) - set(oc))}")
    same = 0
    for name in sorted(set(oc) & set(nc)):
        o, n = norm(oc[name]), norm(nc[name])
        parts = [k for k in ("body", "answers", "sharedWorkspace", "once") if o.get(k) != n.get(k)]
        if not parts:
            same += 1
            continue
        print(f"\n== {name}: differs in {', '.join(parts)}; input items {len(o['body']['input'])} -> {len(n['body']['input'])}; "
              f"once {o.get('once')} -> {n.get('once')}")
        found = diffs(o.get("body"), n.get("body"))
        for path, a, b in found[:limit]:
            print(f"   body{path}\n      old: {short(a)}\n      new: {short(b)}")
        if len(found) > limit:
            print(f"   ... {len(found) - limit} more body paths")
        if "answers" in parts:
            found = diffs(o.get("answers"), n.get("answers"))
            for path, a, b in found[:2]:
                print(f"   answers{path}\n      old: {short(a)}\n      new: {short(b)}")
            print(f"   answers: {len(found)} differing paths")
    print(f"\nunchanged cases: {same}")


main()

